        "prices.newerSchema": Entry("有新格式的價格表，請更新 Agent Speed", "有新格式的价格表，请更新 Agent Speed", "A newer price table format is available — update Agent Speed to use it", "新しい形式の価格表があります。Agent Speed をアップデートしてください"),
        "prices.status": Entry("版本 %d · %@ 更新 · %d 個模型", "版本 %d · %@ 更新 · %d 个模型", "Version %d · updated %@ · %d models", "バージョン %d · %@ 更新 · %d モデル"),
        "prices.title": Entry("價格表", "价格表", "Price Table", "価格表"),
